دالة أكثر_تكرارا(ق) {
    متغير تكرار = {}
    من_أجل (ع في ق) {
        إذا (يحوي(تكرار، ع)) {
            تكرار[ع] = تكرار[ع] + ١
        } وإلا {
            تكرار[ع] = ١
        }
    }
    متغير ن = لاشيء
    من_أجل (مفتاح في مفاتيح(تكرار)) {
        إذا (ن == لاشيء أو تكرار[مفتاح] > تكرار[ن] أو (تكرار[مفتاح] == تكرار[ن] و مفتاح < ن)) {
            ن = مفتاح
        }
    }
    ارجع ن
}
